    // 2. ФУНКЦИЯ СОХРАНЕНИЯ НАСТРОЕК (РАДАР + ТАБЛО + ВРЕМЯ) В TXT И LOCALSTORAGE
    window.saveSettingsToTxt = function(key, value) {
        if (key && value !== undefined) {
            localStorage.setItem(key, String(value));
        }

        const radarMode = localStorage.getItem('radar_mode') || 'default';
        const captureMode = localStorage.getItem('capture_mode') || '1';
        const timeMode = localStorage.getItem('time_mode') || 'default';

        const txtContent = `radar_mode=${radarMode}\ncapture_mode=${captureMode}\ntime_mode=${timeMode}`;

        localStorage.setItem('mrl_hud_settings.txt', txtContent);
        localStorage.setItem('mrl_hud_config', txtContent);

        try {
            // Эмуляция генерации файла mrl_hud_settings.txt
            const blob = new Blob([txtContent], { type: 'text/plain;charset=utf-8' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = 'mrl_hud_settings.txt';
            link.style.display = 'none';
            document.body.appendChild(link);
            setTimeout(() => { link.remove(); }, 1000);
        } catch(e) {}
    };

